static final class Pair {
    private final Object first;
    private final Object second;

    Pair(Object first, Object second) {
        this.first = first;
        this.second = second;
    }

    Object first() {
        return first;
    }

    Object second() {
        return second;
    }

    Pair swapped() {
        return new Pair(second, first);
    }
}

